import{_ as t,c as n,o,a5 as a}from"./chunks/framework.DYgWcJ6Z.js";const h=JSON.parse('{"title":"Unity embedder API","description":"","frontmatter":{},"headers":[],"relativePath":"manual/references/embedder-guides/unity-apis.md","filePath":"manual/references/embedder-guides/unity-apis.md","lastUpdated":1754235051000}'),r={name:"manual/references/embedder-guides/unity-apis.md"};function i(s,e,d,p,c,l){return o(),n("div",null,e[0]||(e[0]=[a('<h1 id="unity-embedder-api" tabindex="-1">Unity embedder API <a class="header-anchor" href="#unity-embedder-api" aria-label="Permalink to &quot;Unity embedder API&quot;">​</a></h1><p>JSAR provides a <a href="https://unity.com/" target="_blank" rel="noreferrer">Unity</a> plugin that allows developers to embed JSAR in their Unity applications. This document describes how to use the JSAR Unity plugin in Unity applications and provides a reference for the Unity API.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>To use the JSAR Unity plugin, you need to have Unity installed on your machine. You can download Unity from the <a href="https://unity.com/" target="_blank" rel="noreferrer">Unity download page</a>.</p><h3 id="supported-platforms" tabindex="-1">Supported platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported platforms&quot;">​</a></h3><p>JSAR Unity SDK supports the following platforms:</p><ul><li>Android arm64</li><li>Windows x86_64</li><li>macOS (x86_64, arm64)</li></ul><p>On Windows and macOS, Unity is commonly used as an editor, JSAR&#39;s plugin supports developing and testing on these platforms but not rendering to the editor&#39;s scene view, developers should build and run the application to see the AR content at Android or YodaOS-Master devices.</p><h3 id="supported-unity-pipelines" tabindex="-1">Supported Unity pipelines <a class="header-anchor" href="#supported-unity-pipelines" aria-label="Permalink to &quot;Supported Unity pipelines&quot;">​</a></h3><p>Currently, JSAR supports the following Unity pipelines:</p><ul><li>Built-in Render Pipeline</li><li>Universal Render Pipeline (URP)</li></ul><h3 id="supported-stereo-rendering-modes" tabindex="-1">Supported stereo rendering modes <a class="header-anchor" href="#supported-stereo-rendering-modes" aria-label="Permalink to &quot;Supported stereo rendering modes&quot;">​</a></h3><p>JSAR supports both multi-pass and single-pass (instanced/multiview) stereo rendering modes. The stereo rendering mode can be configured using the <code>XRSettings.stereoRenderingMode</code> property in Unity, or check out your Unity XR provider&#39;s documentation for more details.</p><h2 id="download-and-installation" tabindex="-1">Download and installation <a class="header-anchor" href="#download-and-installation" aria-label="Permalink to &quot;Download and installation&quot;">​</a></h2><p>Currently JSAR Unity plugin is not available in the Unity Asset Store or any other public registries because it&#39;s in alpha, if you are interested in using JSAR Unity plugin, please contact us at <a href="https://forum.rokid.com/" target="_blank" rel="noreferrer">Rokid Forum</a>.</p><h2 id="usage-guide" tabindex="-1">Usage guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to &quot;Usage guide&quot;">​</a></h2><p>In this section, we will guide you in using this plugin both in the built-in render pipeline and the Universal Render Pipeline (URP).</p><blockquote><p>Coming soon</p></blockquote><h2 id="c-api-reference" tabindex="-1">C# API Reference <a class="header-anchor" href="#c-api-reference" aria-label="Permalink to &quot;C# API Reference&quot;">​</a></h2><h3 id="class-transmute" tabindex="-1">Class <code>Transmute</code> <a class="header-anchor" href="#class-transmute" aria-label="Permalink to &quot;Class `Transmute`&quot;">​</a></h3><p>This class is the main entry point for the JSAR Unity plugin. It provides methods to start and stop the JSAR runtime, and start the applets (namely the Web applications) in your Unity scene.</p><h4 id="static-properties" tabindex="-1">Static properties <a class="header-anchor" href="#static-properties" aria-label="Permalink to &quot;Static properties&quot;">​</a></h4><p><strong><code>TransmuteFeature RendererFeature</code></strong></p><p>This property is set at the Universal Render Pipeline (URP), you can access it to get the renderer feature instance.</p><p><strong><code>Transmute Instance</code></strong></p><p>The <code>Transmute</code> must be a singleton, this static property provides the singleton instance of the <code>Transmute</code> class.</p><p><strong><code>string ApplicationCacheDirectory</code></strong></p><p>The path to the application cache directory, or set it to customize the cache directory.</p><h4 id="static-methods" tabindex="-1">Static methods <a class="header-anchor" href="#static-methods" aria-label="Permalink to &quot;Static methods&quot;">​</a></h4><p><strong><code>MainControllerInputSource GetMainControllerInputSource()</code></strong></p><p>Get the main controller input source to update.</p><p><strong><code>ScreenControllerInputSource GetScreenControllerInputSource(int index)</code></strong></p><p>Get the screen controller input source to update, the int parameter is the screen-controller index.</p><p><strong><code>HandedInputSource GetHandInputSource(int handness)</code></strong></p><p>Get the handed input source to update, the int parameter is the handness index, 0 for left hand, 1 for right hand.</p><p><strong><code>void SetHandInputSourcesEnabled(bool enabled)</code></strong></p><p>Enable or disable the handed input sources.</p><h4 id="instance-properties" tabindex="-1">Instance properties <a class="header-anchor" href="#instance-properties" aria-label="Permalink to &quot;Instance properties&quot;">​</a></h4><p><strong><code>Camera CameraToUse</code></strong></p><p>The camera to use for rendering the Web content, not working in the Universal Render Pipeline (URP).</p><p><strong><code>LayerMask LightLayerToUse</code></strong></p><blockquote><p>This property is not implemented yet.</p></blockquote><p>Select a layer which contains the lights to use for rendering the Web content.</p><p><strong><code>Vector3 AppletBoxPosition</code></strong></p><p>The initial position of the applet bounding box&#39;s position when an WebXR application is started in <code>local</code> reference space.</p><p><strong><code>GameObject AppletPrefab</code></strong></p><p>The prefab to use for initializing the applet&#39;s GameObject.</p><p><strong><code>string HttpsProxyServer</code></strong></p><p>The HTTPS proxy server to use for applet networking such as <code>https://proxy.server:port</code>.</p><p><strong><code>bool DisableExecCache</code></strong></p><p>Disable the cache, if true, the cache will be disabled, it means any applet will be loaded from the network and will not write related files to the cache directory.</p><p><strong><code>List&lt;TransmuteApplet&gt; Applets</code></strong></p><p>The list of applets that are currently running.</p><h4 id="instance-events-and-actions" tabindex="-1">Instance events and actions <a class="header-anchor" href="#instance-events-and-actions" aria-label="Permalink to &quot;Instance events and actions&quot;">​</a></h4><p><strong><code>UnityEvent&lt;GameObject, TransmuteApplet&gt; OnAppletCreated</code></strong></p><p>This event is triggered when an applet is created.</p><ul><li><code>GameObject</code> is the GameObject that contains the applet.</li><li><code>TransmuteApplet</code> is the <code>TransmuteApplet</code> instance that represents the applet.</li></ul><p><strong><code>UnityEvent&lt;GameObject&gt; OnXRSessionCreated</code></strong></p><p>This event is triggered when an XR session is created.</p><p><strong><code>UnityEvent&lt;GameObject&gt; OnXRSessionEnded</code></strong></p><p>This event is triggered when an XR session is ended.</p><p><strong><code>UnityEvent&lt;GameObject&gt; OnLoading</code></strong></p><p>This event is triggered when the applet is loading.</p><p><strong><code>UnityEvent&lt;GameObject&gt; OnLoaded</code></strong></p><p>This event is triggered when the applet is loaded.</p><p><strong><code>UnityEvent&lt;GameObject&gt; OnError</code></strong></p><p>This event is triggered when an error occurs.</p><p><strong><code>Action&lt;string, string&gt; OnWindowOpen</code></strong></p><p>This action is triggered when a <code>window.open()</code> event is called in an applet, the first parameter is the URL to open, and the second parameter is the target. The implementator should handle this request if needed.</p><p><strong><code>Action&lt;string&gt; OnWindowAlert</code></strong></p><p>This action is triggered when a <code>window.alert()</code> event is called in an applet, the parameter is the message to alert. The implementator should handle this request if needed.</p><p><strong><code>Action&lt;string&gt; OnWindowPrompt</code></strong></p><p>This action is triggered when a <code>window.prompt()</code> event is called in an applet, the parameter is the message to prompt. The implementator should handle this request if needed.</p><h4 id="instance-methods" tabindex="-1">Instance methods <a class="header-anchor" href="#instance-methods" aria-label="Permalink to &quot;Instance methods&quot;">​</a></h4><p><strong><code>TransmuteApplet CreateApplet(string url)</code></strong></p><p>This creates an applet from the given URL and returns the <code>TransmuteApplet</code> instance.</p><p><strong><code>void DestroyApplets()</code></strong></p><p>This destroys all the applets that are currently running.</p><h3 id="enum-transmuteinputevent-inputsourceactionstate" tabindex="-1">Enum <code>TransmuteInputEvent.InputSourceActionState</code> <a class="header-anchor" href="#enum-transmuteinputevent-inputsourceactionstate" aria-label="Permalink to &quot;Enum `TransmuteInputEvent.InputSourceActionState`&quot;">​</a></h3><p>This enum represents the action state of an input source, it has two values: <code>Pressed</code> and <code>Released</code>.</p><ul><li><code>Pressed</code> means the action button is pressed.</li><li><code>Released</code> means the action button is released.</li></ul><h3 id="enum-transmuteinputevent-handjointindex" tabindex="-1">Enum <code>TransmuteInputEvent.HandJointIndex</code> <a class="header-anchor" href="#enum-transmuteinputevent-handjointindex" aria-label="Permalink to &quot;Enum `TransmuteInputEvent.HandJointIndex`&quot;">​</a></h3><p>This enum represents the joint index of the hand, it has the following values:</p><ul><li><code>WRIST</code></li><li><code>THUMB_METACARPAL</code></li><li><code>THUMB_PROXIMAL</code></li><li><code>THUMB_DISTAL</code></li><li><code>THUMB_TIP</code></li><li><code>INDEX_FINGER_METACARPAL</code></li><li><code>INDEX_FINGER_PHALANX_PROXIMAL</code></li><li><code>INDEX_FINGER_PHALANX_INTERMEDIATE</code></li><li><code>INDEX_FINGER_PHALANX_DISTAL</code></li><li><code>INDEX_FINGER_TIP</code></li><li><code>MIDDLE_FINGER_METACARPAL</code></li><li><code>MIDDLE_FINGER_PHALANX_PROXIMAL</code></li><li><code>MIDDLE_FINGER_PHALANX_INTERMEDIATE</code></li><li><code>MIDDLE_FINGER_PHALANX_DISTAL</code></li><li><code>MIDDLE_FINGER_TIP</code></li><li><code>RING_FINGER_METACARPAL</code></li><li><code>RING_FINGER_PHALANX_PROXIMAL</code></li><li><code>RING_FINGER_PHALANX_INTERMEDIATE</code></li><li><code>RING_FINGER_PHALANX_DISTAL</code></li><li><code>RING_FINGER_TIP</code></li><li><code>LITTLE_FINGER_METACARPAL</code></li><li><code>LITTLE_FINGER_PHALANX_PROXIMAL</code></li><li><code>LITTLE_FINGER_PHALANX_INTERMEDIATE</code></li><li><code>LITTLE_FINGER_PHALANX_DISTAL</code></li><li><code>LITTLE_FINGER_TIP</code></li><li><code>END</code></li></ul><h3 id="class-transmuteinputevent-xrinputsource" tabindex="-1">Class <code>TransmuteInputEvent.XRInputSource</code> <a class="header-anchor" href="#class-transmuteinputevent-xrinputsource" aria-label="Permalink to &quot;Class `TransmuteInputEvent.XRInputSource`&quot;">​</a></h3><p>This is a base class for all the input sources: <code>MainControllerInputSource</code>, <code>ScreenControllerInputSource</code>, <code>HandedInputSource</code> and new input sources in the future.</p><p>To get the corresponding input source, you still need to use the static methods in the <code>Transmute</code> class, this is because the input sources are global and shared among all the applets, when there is an input source update, all the applets are able to get the update.</p><h4 id="instance-properties-1" tabindex="-1">Instance properties <a class="header-anchor" href="#instance-properties-1" aria-label="Permalink to &quot;Instance properties&quot;">​</a></h4><p><strong><code>bool Enabled</code></strong></p><p>If the input source is enabled or not.</p><p><strong><code>int Id</code></strong></p><p>The input source id.</p><h4 id="instance-methods-1" tabindex="-1">Instance methods <a class="header-anchor" href="#instance-methods-1" aria-label="Permalink to &quot;Instance methods&quot;">​</a></h4><p><strong><code>void SetEnabled(bool enabled)</code></strong></p><p>Enable or disable the input source.</p><p><strong><code>void SetTargetRayPose(Pose pose)</code></strong></p><p>The target ray for an input source is the ray that is used to interact with the applet, this method sets the pose of the target ray.</p><ul><li>The <code>pose</code> parameter is the pose of the target ray to update.</li></ul><p><strong><code>void SetGripPose(Pose pose)</code></strong></p><p>The grip pose for an input source is the pose when the user is holding the input device, this method sets the pose of the grip.</p><ul><li>The <code>pose</code> parameter is the pose of the grip to update.</li></ul><p><strong><code>void SetPrimaryActionState(TransmuteInputEvent.InputSourceActionState state)</code></strong></p><p>At WebXR, the primary action is defined as an action that is triggered by the primary button, the implementor should use this method to update the primary action state (pressed or released) of the input source.</p><ul><li>The <code>state</code> parameter is the state of the primary action.</li></ul><p><strong><code>void SetSqueezeActionState(TransmuteInputEvent.InputSourceActionState state)</code></strong></p><p>Similar to the primary action, the squeeze action is also defined by the implementor and used by the application developers.</p><ul><li>The <code>state</code> parameter is the state of the squeeze action.</li></ul><h3 id="class-transmuteinputevent-maincontrollerinputsource" tabindex="-1">Class <code>TransmuteInputEvent.MainControllerInputSource</code> <a class="header-anchor" href="#class-transmuteinputevent-maincontrollerinputsource" aria-label="Permalink to &quot;Class `TransmuteInputEvent.MainControllerInputSource`&quot;">​</a></h3><p>This class represents the main controller input source and inherits from <code>TransmuteInputEvent.XRInputSource</code>. No new properties or methods are added to this class, please refer to the base class <code>TransmuteInputEvent.XRInputSource</code> for more details.</p><h3 id="class-transmuteinputevent-screencontrollerinputsource" tabindex="-1">Class <code>TransmuteInputEvent.ScreenControllerInputSource</code> <a class="header-anchor" href="#class-transmuteinputevent-screencontrollerinputsource" aria-label="Permalink to &quot;Class `TransmuteInputEvent.ScreenControllerInputSource`&quot;">​</a></h3><p>This class represents the screen controller input source and inherits from <code>TransmuteInputEvent.XRInputSource</code>. No new properties or methods are added to this class, please refer to the base class <code>TransmuteInputEvent.XRInputSource</code> for more details.</p><h3 id="class-transmuteinputevent-handedinputsource" tabindex="-1">Class <code>TransmuteInputEvent.HandedInputSource</code> <a class="header-anchor" href="#class-transmuteinputevent-handedinputsource" aria-label="Permalink to &quot;Class `TransmuteInputEvent.HandedInputSource`&quot;">​</a></h3><p>This class represents the handed input source and inherits from <code>TransmuteInputEvent.XRInputSource</code>.</p><h4 id="instance-properties-2" tabindex="-1">Instance properties <a class="header-anchor" href="#instance-properties-2" aria-label="Permalink to &quot;Instance properties&quot;">​</a></h4><p><strong><code>int Handness</code></strong></p><p>The handness of the input source, 0 for left hand, 1 for right hand.</p><h4 id="instance-methods-2" tabindex="-1">Instance methods <a class="header-anchor" href="#instance-methods-2" aria-label="Permalink to &quot;Instance methods&quot;">​</a></h4><p><strong><code>void SetJoint(TransmuteInputEvent.HandJointIndex index, Vector3 position, Quaternion rotation)</code></strong></p><p>Set the joint position and rotation of the hand.</p><ul><li>The <code>index</code> parameter is the joint index, see <code>TransmuteInputEvent.HandJointIndex</code> for more details.</li><li>The <code>position</code> parameter is the position of the joint.</li><li>The <code>rotation</code> parameter is the rotation of the joint.</li></ul><p><strong><code>void ResetJoints()</code></strong></p><p>Reset all the joints of the hand to the default pose, the implementor should call this method when the hand is not tracked.</p>',122)]))}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
